// Only rows that are waiting for a demo: a lead nobody has contacted yet that
// has no demo link on it. The batch stays small on purpose, because each demo
// costs an API call and produces a page a real prospect will open.
const MAX = Number($env.COUDERS_DEMO_BATCH ?? 10);
const rows = $json.rows ?? [];

const wanted = rows.filter((r) => {
  const status = String(r.status ?? 'nowy').toLowerCase();
  const domain = String(r.domena ?? '').trim();
  return status === 'nowy' && !String(r.demoUrl ?? '').trim() && domain;
});

return wanted.slice(0, MAX).map((r) => ({
  json: {
    rowId: r.rowId,
    company: r.firma ?? '',
    domain: String(r.domena).replace(/^https?:\/\//, '').replace(/\/.*$/, ''),
    person: r.osoba ?? '',
  },
}));

// Turns the fetched page into plain text the model can read, keeping only as
// much as is useful: the first ~12k characters of a company site reliably
// carry the offer, the catalogue headings and the pricing cues.
//
// The lead comes from the loop node rather than from the node before it:
// inside a batch loop that is the only reference that resolves to the company
// being processed right now.
const lead = $('Po jednej firmie').first().json;
const html = String($json.data ?? $json.body ?? '');

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<nav[\s\S]*?<\/nav>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, ' ')
  .trim();

if (text.length < 400) {
  // Too little to build anything convincing. No demo beats a demo that tells
  // the prospect you never looked at their business.
  return [{ json: { ...lead, skip: 'za mało treści na stronie', pageText: '' } }];
}

return [{ json: { ...lead, pageText: text.slice(0, 12000) } }];

// The model is asked for bare JSON, but a stray code fence or a sentence of
// preamble should not cost the whole run. Parse defensively, then insist on
// the fields the demo page and the e-mail template actually need.
const lead = $('Po jednej firmie').first().json;

if ($json.skip) return [{ json: { ...lead, skip: $json.skip } }];

const raw = $json.content?.[0]?.text ?? '';

function extract(s) {
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = (fenced ? fenced[1] : s).trim();
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1) return null;
  try { return JSON.parse(candidate.slice(start, end + 1)); } catch { return null; }
}

const cfg = extract(raw);
const required = ['company', 'intro', 'suggested', 'facts', 'systemPrompt', 'emailDetail'];
const missing = cfg ? required.filter((k) => !cfg[k]) : required;

if (!cfg || missing.length) {
  return [{ json: { ...lead, skip: 'model nie zwrócił kompletnej konfiguracji: ' + missing.join(', ') } }];
}
if (!Array.isArray(cfg.facts) || cfg.facts.length < 3) {
  return [{ json: { ...lead, skip: 'za mało wiedzy o firmie, demo byłoby puste' } }];
}

// An unguessable suffix keeps one prospect's demo out of another's hands and
// stops the target list from being enumerable by walking slugs.
const slug = String(cfg.company).toLowerCase()
  .normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 24) || 'demo';
const token = slug + '-' + Math.random().toString(36).slice(2, 8);

const days = Number($env.COUDERS_DEMO_TTL_DAYS ?? 7);
const expires = new Date(Date.now() + days * 86400000);
const base = $env.COUDERS_SITE_URL ?? 'https://couders.com';

return [{
  json: {
    ...lead,
    token,
    demoUrl: base + '/pl/demo/?id=' + token,
    expiresAt: expires.toISOString(),
    demoExpiry: expires.toLocaleDateString('pl-PL', { day: 'numeric', month: 'long' }),
    config: { ...cfg, token, expiresAt: expires.toISOString() },
  },
}];
